package com.axiom.persistence;
import com.axiom.IntegrationTestSupport; import com.axiom.application.pipeline.PipelinePersistenceService; import com.axiom.domain.pipeline.*; import java.util.List; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.jdbc.core.JdbcTemplate; import static org.assertj.core.api.Assertions.assertThat;
class PipelinePersistenceServiceTest extends IntegrationTestSupport {
 @Autowired PipelinePersistenceService service; @Autowired JdbcTemplate jdbc;
 @Test void reingestionIsIdempotentButAttemptsRemainDistinct(){var one=run(1,PipelineConclusion.FAILURE);var first=service.save(one);var same=service.save(one);var second=service.save(run(2,PipelineConclusion.SUCCESS));assertThat(first.id()).isEqualTo(same.id());assertThat(second.id()).isNotEqualTo(first.id());assertThat(jdbc.queryForObject("select count(*) from pipeline_runs where external_run_id=99",Integer.class)).isEqualTo(2);assertThat(jdbc.queryForObject("select count(*) from pipeline_jobs j join pipeline_runs r on r.id=j.pipeline_run_id where r.external_run_id=99",Integer.class)).isEqualTo(2);}
 private PipelineRun run(int attempt,PipelineConclusion conclusion){var step=new PipelineStep(1,"step",PipelineStatus.COMPLETED,conclusion,null,null);var job=new PipelineJob(UUID.randomUUID(),8,"job",PipelineStatus.COMPLETED,conclusion,"runner",null,null,List.of(step));return new PipelineRun(UUID.randomUUID(),CiProviderType.GITHUB_ACTIONS,99,"owner","repo","sha","base","push","main",null,PipelineStatus.COMPLETED,conclusion,attempt,null,null,List.of(job));}
}
